#!/usr/bin/env python3
"""Complete compact Arrange controls for Design 2.0 Inspector."""

def install(html):
    css=r'''<style id="d2-arrange-css">#d2-arrange{margin-top:12px}.d2-arrange-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.d2-arrange-grid button,.d2-group-actions button,.d2-arrange-wide button{margin:0!important;padding:6px 4px!important;font:9px Inter,sans-serif!important}.d2-group-actions,.d2-arrange-wide{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:5px}.d2-group-readout{margin:6px 0;color:#8b8579;font:9px ui-monospace,monospace}.d2-gap{display:grid;grid-template-columns:1fr 54px;gap:5px;margin-top:5px}.d2-gap input{width:100%;box-sizing:border-box;border:1px solid #d9d3c7;background:#fbfaf6;padding:5px;font:9px ui-monospace,monospace}</style>'''
    panel=r'''<div id="d2-arrange"><div class="d2-section-title">ARRANGE</div><div id="d2-selection-readout" class="d2-group-readout">1 selected</div><div class="d2-arrange-grid"><button data-align="left">Left</button><button data-align="center">Center</button><button data-align="right">Right</button><button data-align="top">Top</button><button data-align="middle">Middle</button><button data-align="bottom">Bottom</button></div><div class="d2-arrange-wide"><button data-center="canvas-x">Center canvas ↔</button><button data-center="canvas-y">Center canvas ↕</button></div><div class="d2-arrange-wide"><button data-distribute="horizontal">Distribute ↔</button><button data-distribute="vertical">Distribute ↕</button></div><div class="d2-gap"><input id="d2-gap" type="number" min="0" value="24" title="Fixed gap"><div class="d2-arrange-wide" style="margin:0"><button data-stack="horizontal">Gap ↔</button><button data-stack="vertical">Gap ↕</button></div></div><div class="d2-arrange-wide"><button data-z="front">Bring front</button><button data-z="forward">Forward</button><button data-z="backward">Backward</button><button data-z="back">Send back</button></div><div class="d2-group-actions"><button id="d2-group">Group</button><button id="d2-ungroup">Ungroup</button></div></div>'''
    js=r'''<script id="d2-arrange-js">(()=>{const g=id=>document.getElementById(id);let ids=[];function currentIds(){return ids.length?ids:(selected?.id?[selected.id]:[])}function send(op,extra={}){const list=currentIds();if(!list.length)return;g('canvas').contentWindow.postMessage({type:'d2-canvas-command',page_id:active,op,ids:list,...extra},'*')}async function zorder(mode){const list=currentIds();if(!list.length)return;const p=ws.pages.find(x=>x.id===active);if(!p)return;let arr=p.nodes.map(n=>n.id);const chosen=arr.filter(id=>list.includes(id));if(mode==='front')arr=arr.filter(id=>!list.includes(id)).concat(chosen);else if(mode==='back')arr=chosen.concat(arr.filter(id=>!list.includes(id)));else{for(const id of (mode==='forward'?[...chosen].reverse():chosen)){let i=arr.indexOf(id),j=mode==='forward'?Math.min(arr.length-1,i+1):Math.max(0,i-1);if(i!==j){[arr[i],arr[j]]=[arr[j],arr[i]]}}}for(let i=0;i<arr.length;i++)await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'reorder_node',page_id:active,id:arr[i],index:i})});location.reload()}document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>send('align_nodes',{mode:b.dataset.align}));document.querySelectorAll('[data-center]').forEach(b=>b.onclick=()=>send('center_nodes',{mode:b.dataset.center,canvas_w:1200,canvas_h:2280}));document.querySelectorAll('[data-distribute]').forEach(b=>b.onclick=()=>send('distribute_nodes',{mode:b.dataset.distribute}));document.querySelectorAll('[data-stack]').forEach(b=>b.onclick=()=>send('stack_nodes',{mode:b.dataset.stack,gap:+g('d2-gap').value||0}));document.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>zorder(b.dataset.z));g('d2-group').onclick=()=>send('group_nodes',{group_id:'group-'+Date.now().toString(36)});g('d2-ungroup').onclick=()=>send('ungroup_nodes');window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-selection-set'&&m.page_id===active){ids=m.ids||[];g('d2-selection-readout').textContent=ids.length+' selected'}if(m.type==='dore-locked'&&m.page_id===active)g('status').textContent='LOCKED · '+m.id});const oldSelect=select;select=function(id,field,value,el){oldSelect(id,field,value,el);if(!ids.includes(id))ids=[id];g('d2-selection-readout').textContent=ids.length+' selected'}})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('</div><p class="hint">Homepage and Journal are separate workspace pages.','</div>'+panel+'<p class="hint">Homepage and Journal are separate workspace pages.',1).replace('</body>',js+'</body>',1)
